package com.bank.intraday.service;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.logging.Logger;

// Shortest continuous run (allowing negatives) whose sum is at least the target.
public class IntradayLiquidityFinder {
    private static final Logger log = Logger.getLogger(IntradayLiquidityFinder.class.getName());

    public int shortestRunToReach(int[] moves, long target) {
        if (moves == null || moves.length == 0) {
            return -1;
        }
        int n = moves.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + moves[i];
        }
        Deque<Integer> dq = new ArrayDeque<>(); // indices into prefix, increasing values
        int best = Integer.MAX_VALUE;

        for (int i = 0; i <= n; i++) {
            // Front: while window qualifies, record length and pop (never needed again).
            while (!dq.isEmpty() && prefix[i] - prefix[dq.peekFirst()] >= target) {
                int j = dq.pollFirst();
                best = Math.min(best, i - j);
                final int len = i - j;
                log.fine(() -> "Qualifying run length " + len + " ending at prefix index " + i);
            }
            // Back: drop dominated (not-smaller) prefixes.
            while (!dq.isEmpty() && prefix[dq.peekLast()] >= prefix[i]) {
                dq.pollLast();
            }
            dq.offerLast(i);
        }
        int result = (best == Integer.MAX_VALUE) ? -1 : best;
        final int r = result;
        log.info(() -> "Shortest run to reach " + target + " over "
                + Arrays.toString(moves) + " = " + r);
        return result;
    }
}
